            while (((cur < content.len) and ((helpers.isBlank(content[@as(usize, @intCast(cur))]) or (content[@as(usize, @intCast(cur))] == 10)) or (content[@as(usize, @intCast(cur))] == 13)))) {
                cur = (cur + 1);
            }
            if (((cur < content.len) and (((content[@as(usize, @intCast(cur))] == 34) or (content[@as(usize, @intCast(cur))] == 39)) or (content[@as(usize, @intCast(cur))] == 40)))) {
                const close_ch: u8 = (if ((content[@as(usize, @intCast(cur))] == 40)) 41 else content[@as(usize, @intCast(cur))]);
                cur = (cur + 1);
                while (((cur < content.len) and (content[@as(usize, @intCast(cur))] != close_ch))) {
                    if (((content[@as(usize, @intCast(cur))] == 92) and ((cur + 1) < content.len))) {
                        cur = (cur + 2);
                    } else {
                        cur = (cur + 1);
                    }
                }
                if ((cur < content.len)) {
                    cur = (cur + 1);
                }
            }
            while (((cur < content.len) and ((helpers.isBlank(content[@as(usize, @intCast(cur))]) or (content[@as(usize, @intCast(cur))] == 10)) or (content[@as(usize, @intCast(cur))] == 13)))) {
                cur = (cur + 1);
            }
            if (((cur < content.len) and (content[@as(usize, @intCast(cur))] == 41))) {
                return .{ .is_link = true, .label_end = label_end, .link_end = (cur + 1) };
            }
        }
        if ((content[@as(usize, @intCast(pos))] == 91)) {
            var cur = (pos + 1);
            _ = &cur;
            while (((cur < content.len) and (content[@as(usize, @intCast(cur))] != 93))) {
                if ((content[@as(usize, @intCast(cur))] == 91)) {
                    break;
                }
                if (((content[@as(usize, @intCast(cur))] == 92) and ((cur + 1) < content.len))) {
                    cur = (cur + 2);
                } else {
                    cur = (cur + 1);
                }
            }
            if (((cur < content.len) and (content[@as(usize, @intCast(cur))] == 93))) {
                const ref_label = (if ((cur > (pos + 1))) content[(pos + 1)..cur] else content[(start + 1)..label_end]);
                if ((p.lookupRefDef(ref_label) != null)) {
                    return .{ .is_link = true, .label_end = label_end, .link_end = (cur + 1) };
                }
            }
        }
        const inner_label = content[(start + 1)..label_end];
        if ((p.lookupRefDef(inner_label) != null)) {
            return .{ .is_link = true, .label_end = label_end, .link_end = (label_end + 1) };
        }
        return .{ .is_link = false, .label_end = label_end, .link_end = (label_end + 1) };
}

pub fn labelContainsLink(p: *Parser, label: []const u8) bool {
        var pos: usize = 0;
        _ = &pos;
        while ((pos < label.len)) {
            if (((label[@as(usize, @intCast(pos))] == 92) and ((pos + 1) < label.len))) {
                pos = (pos + 2);
                continue;
            }
            if ((label[@as(usize, @intCast(pos))] == 96)) {
                const count = inlines_mod.countBackticks(label, pos);
                if (p.findCodeSpanEnd(label, (pos + count), count)) |end_pos| {
                    _ = &end_pos;
                    pos = (end_pos + count);
                    continue;
                }
            }
            if (((label[@as(usize, @intCast(pos))] == 60) and (!p.flags.no_html_spans))) {
                if (p.findHtmlTag(label, pos)) |tag_end| {
                    _ = &tag_end;
                    pos = tag_end;
                    continue;
                }
                if (p.findAutolink(label, pos)) |al| {
                    _ = &al;
                    pos = al.end_pos;
                    continue;
                }
            }
            if ((label[@as(usize, @intCast(pos))] == 91)) {
                const is_inner_image = ((pos > 0) and (label[@as(usize, @intCast((pos - 1)))] == 33));
                const inner = p.tryMatchBracketLink(label, pos);
                if ((inner.is_link and (!is_inner_image))) {
                    return true;
                }
                if ((inner.link_end > pos)) {
                    pos = inner.link_end;
                    continue;
                }
            }
            pos = (pos + 1);
        }
        return false;
}

pub fn processWikiLink(p: *Parser, content: []const u8, start: usize) Parser.Error!?usize {
        var pos = (start + 2);
        _ = &pos;
        const inner_start = pos;
        var pipe_pos: ?usize = null;
        _ = &pipe_pos;
        var bracket_depth: u32 = 0;
        _ = &bracket_depth;
        while ((pos < content.len)) {
            if (((content[@as(usize, @intCast(pos))] == 10) or (content[@as(usize, @intCast(pos))] == 13))) {
                return null;
            }
            if ((content[@as(usize, @intCast(pos))] == 91)) {
                bracket_depth = (bracket_depth + 1);
            } else {
                if ((content[@as(usize, @intCast(pos))] == 93)) {
                    if ((bracket_depth > 0)) {
                        bracket_depth = (bracket_depth - 1);
                    } else {
                        if ((((pos + 1) < content.len) and (content[@as(usize, @intCast((pos + 1)))] == 93))) {
                            break;
                        } else {
                            return null;
                        }
                    }
                } else {
                    if ((((content[@as(usize, @intCast(pos))] == 124) and (pipe_pos == null)) and (bracket_depth == 0))) {
                        pipe_pos = pos;
                    }
                }
            }
            pos = (pos + 1);
        }
        if (((pos >= content.len) or (content[@as(usize, @intCast(pos))] != 93))) {
            return null;
        }
        const inner_end = pos;
        var target = content[inner_start..inner_end];
        _ = &target;
        var label = target;
        _ = &label;
        if (pipe_pos) |pp| {
            _ = &pp;
            target = content[inner_start..pp];
            label = content[(pp + 1)..inner_end];
        }
        if ((target.len > 100)) {
            return null;
        }
        _ = try p.renderer.enterSpan(.wikilink, .{ .href = target });
        _ = try p.processInlineContent(label, 0);
        _ = try p.renderer.leaveSpan(.wikilink);
        return (pos + 2);
}

pub fn renderRefLink(p: *Parser, label_content: []const u8, ref_def: RefDef, is_image: bool) Parser.Error!void {
        if ((p.image_nesting_level > 0)) {
            _ = try p.processInlineContent(label_content, 0);
        } else {
            if (is_image) {
                _ = try p.renderer.enterSpan(.img, .{ .href = ref_def.dest, .title = ref_def.title });
                p.image_nesting_level = (p.image_nesting_level + 1);
                _ = try p.processInlineContent(label_content, 0);
                p.image_nesting_level = (p.image_nesting_level - 1);
                _ = try p.renderer.leaveSpan(.img);
            } else {
                _ = try p.renderer.enterSpan(.a, .{ .href = ref_def.dest, .title = ref_def.title });
                p.link_nesting_level = (p.link_nesting_level + 1);
                _ = try p.processInlineContent(label_content, 0);
                p.link_nesting_level = (p.link_nesting_level - 1);
                _ = try p.renderer.leaveSpan(.a);
            }
        }
}

pub fn findAutolink(p: *const Parser, content: []const u8, start: usize) ?AutolinkResult {
        var _u = p;
        _ = &_u;
        if (((start + 1) >= content.len)) {
            return null;
        }
        const pos = (start + 1);
        if (helpers.isAlpha(content[@as(usize, @intCast(pos))])) {
            var scheme_end = pos;
            _ = &scheme_end;
            while (((scheme_end < content.len) and (((helpers.isAlphaNum(content[@as(usize, @intCast(scheme_end))]) or (content[@as(usize, @intCast(scheme_end))] == 43)) or (content[@as(usize, @intCast(scheme_end))] == 45)) or (content[@as(usize, @intCast(scheme_end))] == 46)))) {
                scheme_end = (scheme_end + 1);
            }
            const scheme_len = (scheme_end - pos);
            if (((((scheme_len >= 2) and (scheme_len <= 32)) and (scheme_end < content.len)) and (content[@as(usize, @intCast(scheme_end))] == 58))) {
                var uri_end = (scheme_end + 1);
                _ = &uri_end;
                while ((((uri_end < content.len) and (content[@as(usize, @intCast(uri_end))] != 62)) and (!helpers.isWhitespace(content[@as(usize, @intCast(uri_end))])))) {
                    uri_end = (uri_end + 1);
                }
                if (((uri_end < content.len) and (content[@as(usize, @intCast(uri_end))] == 62))) {
                    return .{ .end_pos = (uri_end + 1), .is_email = false };
                }
            }
            var email_pos = pos;
            _ = &email_pos;
            while (((email_pos < content.len) and ((((helpers.isAlphaNum(content[@as(usize, @intCast(email_pos))]) or (content[@as(usize, @intCast(email_pos))] == 46)) or (content[@as(usize, @intCast(email_pos))] == 45)) or (content[@as(usize, @intCast(email_pos))] == 95)) or (content[@as(usize, @intCast(email_pos))] == 43)))) {
                email_pos = (email_pos + 1);
            }
            if ((((email_pos < content.len) and (content[@as(usize, @intCast(email_pos))] == 64)) and (email_pos > pos))) {
                email_pos = (email_pos + 1);
                const domain_start = email_pos;
                var label_len: u32 = 0;
                _ = &label_len;
                var dot_count: u32 = 0;
                _ = &dot_count;
                var valid_domain = true;
                _ = &valid_domain;
                while (((email_pos < content.len) and ((helpers.isAlphaNum(content[@as(usize, @intCast(email_pos))]) or (content[@as(usize, @intCast(email_pos))] == 46)) or (content[@as(usize, @intCast(email_pos))] == 45)))) {
                    if ((content[@as(usize, @intCast(email_pos))] == 46)) {
                        if ((label_len == 0)) {
                            valid_domain = false;
                            break;
                        }
                        label_len = 0;
                        dot_count = (dot_count + 1);
                    } else {
                        label_len = (label_len + 1);
                        if ((label_len > 63)) {
                            valid_domain = false;
                            break;
                        }
                    }
                    email_pos = (email_pos + 1);
                }
                if (((((((valid_domain and (email_pos < content.len)) and (content[@as(usize, @intCast(email_pos))] == 62)) and (email_pos > domain_start)) and (label_len > 0)) and (dot_count > 0)) and helpers.isAlphaNum(content[@as(usize, @intCast((email_pos - 1)))]))) {
                    return .{ .end_pos = (email_pos + 1), .is_email = true };
                }
            }
        }
        return null;
}

pub fn renderAutolink(p: *Parser, url: []const u8, is_email: bool) bun.JSError!void {
        _ = try p.renderer.enterSpan(.a, .{ .href = url, .autolink = true, .autolink_email = is_email });
        _ = try p.emitText(.normal, url);
        _ = try p.renderer.leaveSpan(.a);
}
